_SRC['p_compare3'] = '# compare.html — round 3: table wraps on phones, honest subject count + modal, post-table CTA, outlined links (14 Sep 2026)\n\nMARK = \'KW:CMP-R3\'\nFILE = \'compare.html\'\n\ndef edits(src):\n    E = []\n    # CSS: after the R2 mobile block\'s closing brace\n    css_anchor = "    .kw-cmp table.cmp tbody tr:last-child td:last-child{border-bottom:none}\\n  }\\n"\n    extra = MODAL_CSS % (MARK, *([\'.kw-cmp\'] * 11)) + \'\'\'  .kw-cmp .after{margin-top:34px;border:1px solid rgba(123,234,90,.25);border-radius:20px;padding:34px 28px;text-align:center;background:linear-gradient(160deg,rgba(18,20,18,.92),rgba(10,10,13,.95))}\n  .kw-cmp .after h3{font-size:clamp(26px,3.4vw,36px);font-weight:700;letter-spacing:-0.04em;line-height:1.06;margin:0}\n  .kw-cmp .after p{font-size:14.5px;line-height:1.6;color:var(--dim);margin:12px auto 0;max-width:46ch}\n  .kw-cmp .after .row{display:flex;gap:14px;justify-content:center;align-items:center;margin-top:22px;flex-wrap:wrap}\n  @media (max-width:700px){\n    .kw-cmp table.cmp{min-width:0 !important;width:100% !important}\n    .kw-cmp table.cmp tbody td,.kw-cmp table.cmp tbody th{white-space:normal !important;overflow-wrap:anywhere}\n    .kw-cmp .after{padding:28px 20px}\n    .kw-cmp .after .cta{width:100%;max-width:340px;text-align:center}\n  }\n\'\'\'\n    E.append((css_anchor, css_anchor + extra, 1))\n    # copy — the subject count, everywhere the page claimed "every subject"\n    E.append((\'      <h2 data-reveal>Every subject, for less than <span style="color:var(--brat)">one hour of tutoring</span> a month.</h2>\\n\',\n              \'      <h2 data-reveal>A month of knowhere costs less than <span style="color:var(--brat)">one hour of tutoring</span>.</h2>\\n\', 1))\n    E.append((\'<div class="s">Every HSC and VCE subject. Parent dashboard included. 7 days free, A$0 today.</div>\',\n              \'<div class="s">15 HSC and 16 VCE subjects on every plan. Parent dashboard included. 7 days free, A$0 today. <a href="#subjects" data-subjects>Which subjects? &rarr;</a></div>\', 1))\n    E.append((\'Competitor prices are from their public pricing pages on 11 September 2026 &#8212; confirm before paying anyone, including us.</p>\',\n              \'Competitor prices are from their public pricing pages on 11 September 2026 &#8212; confirm before paying anyone, including us. More subjects arrive through 2027 and are included in your plan when they land.</p>\', 1))\n    E.append((\'<p><b>Costs:</b> A$23–39/month, every subject on every plan. 7 days free, A$0 today.</p>\',\n              \'<p><b>Costs:</b> A$23–39/month, 15 HSC and 16 VCE subjects on every plan. 7 days free, A$0 today.</p>\', 1))\n    E.append((\'<small>A$276–468/yr · every subject</small>\', \'<small>A$276–468/yr · 15 HSC + 16 VCE subjects</small>\', 1))\n    E.append((\'<td data-col="knowhere" class="kw">A$276–468, every subject</td>\', \'<td data-col="knowhere" class="kw">A$276–468 for 15 HSC + 16 VCE subjects</td>\', 1))\n    E.append((\'<span class="sr">Yes: </span>Every HSC + VCE subject, every plan</td>\',\n              \'<span class="sr">Yes: </span>15 HSC + 16 VCE subjects, every plan. <a href="#subjects" data-subjects>Which? &rarr;</a></td>\', 1))\n    E.append(("every HSC and VCE subject is included on every plan, and it\'s cheaper",\n              "15 HSC and 16 VCE subjects are included on every plan, and it\'s cheaper", 1))\n    E.append(("yes: every HSC and VCE subject is included on every knowhere plan, and it is cheaper",\n              "yes: 15 HSC and 16 VCE subjects are included on every knowhere plan, and it is cheaper", 1))   # FAQ schema\n    E.append((\'knowhere: A$276–468 a year covers every subject.\', \'knowhere: A$276–468 a year covers 15 HSC and 16 VCE subjects.\', 2))   # body + FAQ schema\n    # post-table CTA block, after the sources note\n    i = src.index(\'      <p class="vnote" data-reveal>Atomi and Edrolo are trademarks\')\n    j = src.index(\'</p>\\n\', i) + len(\'</p>\\n\')\n    vnote = src[i:j]\n    after = \'\'\'      <div class="after" data-reveal>\n        <h3>Worth a <span style="color:var(--brat)">week</span>?</h3>\n        <p>7 days free, A$0 today. Cancel before it ends and you pay nothing. If it doesn&#8217;t click, it cost you a week.</p>\n        <div class="row">\n          <a class="cta" href="https://app.knowhere.me/signup?as=parent">Start their free week</a>\n          <a class="no" href="/experience-it">No &#8212; I want to see it in action first &rarr;</a>\n        </div>\n      </div>\n\'\'\'\n    E.append((vnote, vnote + after, 1))\n    # modal + js\n    foot = \'  <x-import component-from-global-scope="knowhere-footer-nav" from="./knowhere-footer.js?v=21"></x-import>\\n\'\n    E.append((foot, modal_html(\'your\') + \'\\n\' + foot, 1))\n    js_anchor = "      this._stopBanner=window.KnowhereParticleBanner(root,\'Compare\',\'compare\');\\n"\n    E.append((js_anchor, js_anchor + (MODAL_JS % MARK), 1))\n    return E\n\ndef receipts(disk):\n    body = disk[disk.index(\'<x-dc>\'):]\n    return {\n        \'table wraps\':            \'.kw-cmp table.cmp{min-width:0 !important;width:100% !important}\' in disk,\n        \'no every-subject claim\': \'every subject\' not in body.lower().replace(\'every concept in every subject\', \'\'),\n        \'subject count x6\':       body.count(\'15 HSC\') + body.count(\'15 hsc\') >= 6,\n        \'modal once, 31 items\':   disk.count(\'id="kwSubjects"\') == 1 and disk[disk.index(\'id="kwSubjects"\'):disk.index(\'</dialog>\')].count(\'<li>\') == 31,\n        \'modal js wired\':         \'dlg.showModal()\' in disk,\n        \'after block\':            disk.count(\'class="after"\') == 1 and \'see it in action first\' in disk,\n        \'secondary link style\':   \'.kw-cmp .hero .alt a,.kw-cmp .strip-row .more,.kw-cmp .after .no\' in disk,\n    }\n'
_SRC['p_labels'] = '# Label consistency pass — every remaining "start knowing" / "let\'s go" CTA becomes "start your free week"\n# and points at the student signup; the shared footer copies the page\'s own nav CTA (label + href) at runtime\n# so parent/teacher pages route correctly. Footer cache key v21 → v22 on every page.\nMARK = \'knowhere-footer.js?v=22\'   # present in every touched file after the pass (comment line in the two .js)\nPER_FILE = True\nFILES = [\'index.html\', \'how-it-works.html\', \'pricing.html\', \'knowhere-footer.js\', \'knowhere-goat-card.js\',\n         \'404.html\', \'compare.html\', \'experience-it.html\', \'for-parents.html\', \'for-teachers.html\',\n         \'know-us.html\', \'mission.html\', \'press.html\', \'privacy.html\', \'talk-to-us.html\', \'terms.html\', \'waitlist.html\']\nSIGNUP = \'https://app.knowhere.me/signup\'\nLABEL = \'start your free week\'\n\ndef edits(src, F):\n    E = []\n    if F == \'index.html\':\n        E.append((\'      <a href="/pricing" class="kp-cta">Start knowing</a>\\n\',\n                  \'      <a href="%s" class="kp-cta">Start your free week</a>\\n\' % SIGNUP, 1))\n        E.append((\'        <a href="/pricing" class="kw-goo kw-goo--m">start knowing</a>\\n\',\n                  \'        <a href="%s" class="kw-goo kw-goo--m">%s</a>\\n\' % (SIGNUP, LABEL), 1))\n    elif F == \'how-it-works.html\':\n        E.append((\'          <a class="ghost" href="/pricing">Start knowing</a>\\n\',\n                  \'          <a class="ghost" href="%s">Start your free week</a>\\n\' % SIGNUP, 1))\n    elif F == \'pricing.html\':\n        E.append((\'href="https://app.knowhere.me/signup">start knowing — free for 7 days</a>\',\n                  \'href="https://app.knowhere.me/signup">%s</a>\' % LABEL, 3))\n        E.append((\'<b>Every HSC and VCE subject</b> — mapped to your syllabus, every concept in the library\',\n                  \'<b>15 HSC and 16 VCE subjects</b> — mapped to your syllabus, every concept in the library; more arrive through 2027, included\', 1))\n        E.append((\'Personalised Knowscapes for every HSC and VCE subject\', \'Personalised Knowscapes for all 15 HSC and 16 VCE subjects\', 1))\n    elif F == \'knowhere-footer.js\':\n        E.append(("\'<a data-kf-goo href=\\"/pricing\\" style=", "\'<a data-kf-goo href=\\"%s\\" style=" % SIGNUP, 1))\n        E.append(("\'<span style=\\"position:relative\\">start knowing</span>\'", "\'<span data-kf-goo-label style=\\"position:relative\\">%s</span>\'" % LABEL, 1))\n        E.append(("\'<div style=\\"margin-top:30px\\"><a href=\\"/pricing\\" style=", "\'<div style=\\"margin-top:30px\\"><a data-kf-nav-cta href=\\"%s\\" style=" % SIGNUP, 1))\n        E.append((">let&#39;s go</a>", ">%s</a>" % LABEL, 1))\n        E.append(("// v20: SOCIAL row", "// v22: one CTA label site-wide (start your free week), footer CTAs mirror the page\'s nav CTA — KW:LABELS (Muppet, 14 Sep); pages load knowhere-footer.js?v=22.\\n// v20: SOCIAL row", 1))\n        # runtime: mirror the page\'s nav CTA (label + destination) into both footer CTAs\n        E.append(("      this._cta = this.querySelector(\'[data-kf-cta]\');\\n",\n                  "      this._cta = this.querySelector(\'[data-kf-cta]\');\\n"\n                  "      window.kwMirrorCta && window.kwMirrorCta(this.querySelector(\'[data-kf-goo]\'), this.querySelector(\'[data-kf-goo-label]\'));\\n", 1))\n        E.append(("        var slot = this.querySelector(\'[data-kfn-logo]\');\\n",\n                  "        window.kwMirrorCta && window.kwMirrorCta(this.querySelector(\'[data-kf-nav-cta]\'), null);\\n"\n                  "        var slot = this.querySelector(\'[data-kfn-logo]\');\\n", 1))\n        E.append(("(function () {\\n", "(function () {\\n"\n                  "  /* KW:LABELS — the footer\'s CTAs say what the page\'s nav CTA says (parents → ?as=parent, teachers → /waitlist) */\\n"\n                  "  window.kwMirrorCta = function (a, labelEl) {\\n"\n                  "    try { var pc = document.querySelector(\'nav:not(.kwm-panel) [data-kw-cta]\'); if (!pc || !a) return;\\n"\n                  "      a.setAttribute(\'href\', pc.getAttribute(\'href\')); (labelEl || a).textContent = (pc.textContent || \'\').trim(); } catch (e) {}\\n"\n                  "  };\\n", 1))\n    elif F == \'knowhere-goat-card.js\':\n        E.append((\'  ctaLabel:"start knowing",\\n  ctaHref:"/pricing",\', \'  ctaLabel:"%s",   /* KW:LABELS 14 Sep — one label site-wide; pages load knowhere-footer.js?v=22 */\\n  ctaHref:"%s",\' % (LABEL, SIGNUP), 1))\n    # every page: footer cache-bust\n    if F.endswith(\'.html\'):\n        E.append((\'knowhere-footer.js?v=21"\', \'knowhere-footer.js?v=22"\', 1))\n    return E\n\ndef receipts(disk, F):\n    R = {}\n    if F.endswith(\'.html\'):\n        R[\'footer v22\'] = \'knowhere-footer.js?v=22\' in disk and \'knowhere-footer.js?v=21\' not in disk\n        R[\'no start knowing\'] = \'start knowing\' not in disk[disk.index(\'<x-dc>\'):].lower() if \'<x-dc>\' in disk else \'start knowing\' not in disk.lower()\n    if F == \'knowhere-footer.js\':\n        R[\'footer labels\'] = disk.count(\'start your free week\') == 3 and ">let&#39;s go</a>" not in disk and \'href="/pricing"\' not in disk\n        R[\'mirror wired\'] = \'window.kwMirrorCta = function\' in disk and disk.count(\'window.kwMirrorCta && window.kwMirrorCta(\') == 2\n    if F == \'knowhere-goat-card.js\':\n        R[\'goat card\'] = \'ctaLabel:"start your free week"\' in disk\n    if F == \'pricing.html\':\n        R[\'three plan buttons + nav\'] = disk.count(\'>start your free week</a>\') == 4\n    return R\n'

_MODS = {}
def _load(name):
    if name in _MODS: return _MODS[name]
    mod = types.ModuleType(name)
    if name == 'p_compare3':
        base = _load('p_parents3'); mod.modal_html = base.modal_html; mod.MODAL_CSS = base.MODAL_CSS; mod.MODAL_JS = base.MODAL_JS
    exec(compile(_SRC[name], name + '.py', 'exec'), mod.__dict__); _MODS[name] = mod; return mod
class _IL:
    @staticmethod
    def import_module(name): return _load(name)
importlib = _IL()

DRY = '--dry' in sys.argv
MODS = [m for m in sys.argv[1:] if not m.startswith("--")] or ["p_parents3", "p_compare3", "p_labels"]

def md5s(s): return hashlib.md5(s.encode('utf-8')).hexdigest()

plan = []      # (mod, name, F, src_for_this_module, out)
orig = {}      # F -> content on disk before anything (backup source)
cur = {}       # F -> latest planned content (modules touching the same file chain)
for name in MODS:
    mod = importlib.import_module(name)
    files = mod.FILES if hasattr(mod, 'FILES') else [mod.FILE]
    for F in files:
        if not os.path.exists(F): sys.exit('missing %s — run from the knowhere-website repo root' % F)
        if F not in orig: orig[F] = open(F, encoding='utf-8').read(); cur[F] = orig[F]
        src = cur[F]
        if mod.MARK in src:
            print('%-22s %-24s already applied (%s)' % (name, F, mod.MARK)); continue
        E = mod.edits(src, F) if getattr(mod, 'PER_FILE', False) else mod.edits(src)
        out = src
        for k, (a, b, n) in enumerate(E):
            c = out.count(a)
            if c != n: sys.exit('PREFLIGHT FAIL %s %s edit #%d: anchor found %d× (expected %d): %r' % (name, F, k, c, n, a[:90]))
            out = out.replace(a, b)
        cur[F] = out
        plan.append((mod, name, F, src, out))
        print('%-22s %-24s %d edits ok  %s → %s' % (name, F, len(E), md5s(src)[:8], md5s(out)[:8]))

if DRY: print('dry run — nothing written'); sys.exit(0)
if not plan: print('nothing to do'); sys.exit(0)

ts = time.strftime('%Y%m%d-%H%M%S')
written = []
for F in [f for f in orig if cur[f] != orig[f]]:
    bak = '%s.bak-%s' % (F, ts)
    open(bak, 'w', encoding='utf-8').write(orig[F])
    open(F, 'w', encoding='utf-8').write(cur[F])
    written.append((F, orig[F], bak))

bad = []
for mod, name, F, src, out in plan:
    disk = open(F, encoding='utf-8').read()
    R = mod.receipts(disk, F) if getattr(mod, 'PER_FILE', False) else mod.receipts(disk)
    R['written = planned'] = (disk == cur[F])
    for k, v in R.items():
        print('  %s %-24s %s' % ('ok  ' if v else 'FAIL', F, k))
        if not v: bad.append((F, k))
if bad:
    for F, src, bak in written: open(F, 'w', encoding='utf-8').write(src)
    sys.exit('RECEIPT FAILURE %r — every file restored; backups kept with suffix .bak-%s' % (bad, ts))
print('applied %d file(s); backups .bak-%s (gitignored)' % (len(written), ts))
